package org.example;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import app.LocalAppTest;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

class AppTest {
    /*@Test
    void appHasAGreeting() {
        //LocalAppTest classUnderTest = new LocalAppTest();
        //assertNotNull(classUnderTest.getGreeting(), "app should have a greeting");
    }*/

    private static LocalAppTest app;
    private static final HttpClient client = HttpClient.newHttpClient();

    @Test
    void testPost() throws Exception {
        // setup
        app = new LocalAppTest();
        app.initializeApp();
        app.startApp();

        // POST test
        HttpRequest postRequest = HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:7070/api/users/"))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(
                    "{\"name\":\"Alice\",\"email\":\"alice@example.com\"}"
                )).build();
        HttpResponse<String> postResponse = client.send(postRequest, HttpResponse.BodyHandlers.ofString());
        System.out.println(postResponse.statusCode());
        System.out.println(postResponse.body());
        // GET test
        HttpRequest getRequest = HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:7070/api/users/1"))
                .GET()
                .build();
        HttpResponse<String> getResponse = client.send(getRequest, HttpResponse.BodyHandlers.ofString());
        System.out.println(getResponse.statusCode());
        System.out.println(postResponse.body());

        // cleanup
        app.stopApp();
    }
}
